package com.panish.ridebooking.ride.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="rides") public class Ride {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long riderId; @Column(nullable=false) private String pickup; @Column(nullable=false) private String dropoff; @Column(nullable=false) private double estimatedFare; @Column(nullable=false) private String status; private Long driverId; private String driverName; @Column(nullable=false) private Instant createdAt=Instant.now(); protected Ride(){} public Ride(Long riderId,String pickup,String dropoff,double fare){this.riderId=riderId;this.pickup=pickup;this.dropoff=dropoff;this.estimatedFare=fare;this.status="REQUESTED";} public Long getId(){return id;} public Long getRiderId(){return riderId;} public String getPickup(){return pickup;} public String getDropoff(){return dropoff;} public double getEstimatedFare(){return estimatedFare;} public String getStatus(){return status;} public Long getDriverId(){return driverId;} public String getDriverName(){return driverName;} public void assign(Long id,String name){driverId=id;driverName=name;status="ASSIGNED";} public void cancelNoDrivers(){status="CANCELLED_NO_DRIVERS";} }